#!/usr/bin/env python3
"""
OGI 物流系统 Bug 修复部署脚本
运行: python3 deploy-fixes.py
"""
import base64, os, subprocess, sys

PROJECT = "/opt/ogi-logistics"
os.chdir(PROJECT)

FILES = [
    ("components/web-sidebar.tsx", """"""),
    ("lib/_core/auth.ts", """"""),
    ("app/oauth/callback.tsx", """"""),
    ("app/crm.tsx", """"""),
    ("app/quote-manage.tsx", """"""),
    ("app/quote-inquiry.tsx", """""")
]

WORKFLOW = """name: Deploy to Server
on:
  push:
    branches: [ main ]
jobs:
  deploy:
    runs-on: ubuntu-latest
    steps:
      - name: Deploy via SSH
        uses: appleboy/ssh-action@v1.0.3
        with:
          host: 8.218.94.187
          username: root
          key: ${{ secrets.SERVER_SSH_KEY }}
          script: |
            cd /opt/ogi-logistics
            git pull origin main
            pm2 restart all
"""

def write(path, content):
    full = os.path.join(PROJECT, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "wb") as f:
        f.write(content)
    print(f"  wrote {path}")

def run(cmd):
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if r.returncode != 0:
        print(f"  ERROR: {r.stderr.strip()}")
    else:
        print(f"  OK: {r.stdout.strip()[:80]}")
    return r.returncode == 0

print("=== OGI Bug 修复部署 ===")
print()
print("[1/4] 写入修复文件...")
for dst, b64 in FILES:
    write(dst, base64.b64decode(b64))

print()
print("[2/4] 写入 GitHub Actions 自动部署配置...")
write(".github/workflows/deploy.yml", WORKFLOW.encode())

print()
print("[3/4] Git 提交并推送...")
run("git add -A")
run('git commit -m "fix: Alert on web, login display, auth security, auto-deploy"')
run("git push origin main")

print()
print("[4/4] 重启 PM2...")
run("pm2 restart all")
run("pm2 status")

print()
print("=== 全部完成！===")
